code='''from collections import Counter

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Locate the first framed row and infer the repeated tile pitch from its runs.
    first = next(r for r, row in enumerate(g) if any(v != 0 for v in row))
    runs = []
    c = 0
    while c < w:
        if g[first][c] == 0:
            c += 1
            continue
        a = c
        while c < w and g[first][c] != 0:
            c += 1
        runs.append((a, c-a))
    tile = max(length for _, length in runs)
    starts = [a for a, length in runs if length == tile]
    diffs = [b-a for a,b in zip(starts, starts[1:]) if b>a]
    pitch = Counter(diffs).most_common(1)[0][0] if diffs else tile + 2
    # Tile centers lie halfway across each repeated framed block.
    off = tile // 2
    rows = list(range(first + off, h, pitch))
    cols = list(range((starts[0] if starts else 1) + off, w, pitch))
    centers = {(r,c): g[r][c] for r in rows for c in cols}
    freq = Counter(v for v in centers.values() if v != 0)
    if not freq:
        return g
    common = freq.most_common(1)[0][0]
    for color in set(freq) - {common}:
        points = [p for p,v in centers.items() if v == color]
        for i, (r1,c1) in enumerate(points):
            for r2,c2 in points[i+1:]:
                if r1 == r2:
                    for c in range(min(c1,c2)+1, max(c1,c2)):
                        if g[r1][c] == 0:
                            g[r1][c] = color
                elif c1 == c2:
                    for r in range(min(r1,r2)+1, max(r1,r2)):
                        if g[r][c1] == 0:
                            g[r][c1] = color
    return g
'''
